n=19
g=[[0]*n for _ in range(n)]
marks=[(2,6),(3,5),(3,7),(4,6), (3,13),(4,12),(4,14),(5,13), (11,14),(12,13),(12,15),(13,14), (13,3),(14,2),(14,4),(15,3), (9,8),(10,7),(10,9),(11,8)]
for r,c in marks:g[r][c]=3
centers={(3,6):8,(4,13):4,(12,14):1,(14,3):2}
# Draw horizontal rows, then vertical columns (vertical wins at line intersections).
for (r,c),v in centers.items():
    for j in range(n):
        if g[r][j]!=3:g[r][j]=v
for (r,c),v in centers.items():
    for i in range(n):
        if g[i][c]!=3:g[i][c]=v
# Center-colored cells supersede any spokes/axis colors.
for (r,c),v in centers.items():g[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in g))

